import React, { useState, useEffect, useRef } from 'react';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { chatApi } from '../services/api';
import type { ChatApi } from '../services/api';
import type { ChatMessage } from '../types';
import MessageInput from './MessageInput';
import { AuthService, handleOAuthCallback } from '../services/authService';
import { isInPopup } from '../utils/authPopup';

export type ChatScreenProps = {
  api?: ChatApi;
  title?: string;
  showHeader?: boolean;
  brandIcon?: React.ReactNode;
  usePopup?: boolean; // Force popup mode (for widget) - URLs are now hardcoded
};

const DefaultBrandIcon = () => (
  <div className="w-6 h-6 rounded-full bg-blue-600 text-white flex items-center justify-center text-xs font-bold">
    O
  </div>
);

const ChatScreen: React.FC<ChatScreenProps> = ({
  api = chatApi,
  title = 'Orion Chat',
  showHeader = true,
  brandIcon,
  usePopup,
}) => {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [isLoadingMore, setIsLoadingMore] = useState(false);
  const [hasMoreMessages, setIsLoadingMoreMessages] = useState(true);
  const [currentPage, setCurrentPage] = useState(1);
  const [, setIsAuthenticated] = useState<boolean | null>(null);
  const messagesContainerRef = useRef<HTMLDivElement>(null);

  // Initialize auth service (memoize to prevent recreation on every render)
  // URLs are now hardcoded in AuthService, no need to pass them
  const authService = React.useMemo(() => {
    return new AuthService({ usePopup });
  }, [usePopup]);

  // Memoize loadMessages to prevent recreation and infinite loops
  const loadMessages = React.useCallback(async (page = 1, append = false) => {
    try {
      if (append) setIsLoadingMore(true);
      else setIsLoading(true);
      const response = await api.getMessages(page, 20);
      const newMessages = response.messages || [];
      if (append) {
        setMessages((prev) => [...prev, ...newMessages]);
      } else {
        setMessages(newMessages);
      }
      setIsLoadingMoreMessages(newMessages.length === 20);
      setCurrentPage(page);
    } catch (error) {
      console.error('Error loading messages:', error);
    } finally {
      setIsLoading(false);
      setIsLoadingMore(false);
    }
  }, [api]);

  useEffect(() => {
    // Handle OAuth callback (for popup mode)
    if (isInPopup()) {
      handleOAuthCallback();
      return;
    }

    // Handle OAuth redirect (for full web app)
    const urlParams = new URLSearchParams(window.location.search);
    const authStatus = urlParams.get('auth');
    const token = urlParams.get('token');

    if (authStatus === 'success' && token) {
      // Set cookie on frontend domain so it's available for API calls
      // Note: Can't be HTTP-only when set from frontend, but still secure with SameSite and Secure
      const isSecure = window.location.protocol === 'https:';
      const cookieOptions = [
        `orion_auth_token=${token}`,
        `path=/`,
        `max-age=${60 * 60 * 24 * 7}`, // 7 days
        `SameSite=None`, // Required for cross-origin
        isSecure ? 'Secure' : '', // Required for SameSite=None
      ].filter(Boolean).join('; ');
      document.cookie = cookieOptions;
      
      // Store in localStorage for reference
      localStorage.setItem('orion_auth_token', token);
      
      // Clean up URL parameters
      const newUrl = window.location.pathname;
      window.history.replaceState({}, '', newUrl);
      
      console.log('✅ Authentication successful');
      setIsAuthenticated(true);
    } else if (authStatus === 'error') {
      const error = urlParams.get('error');
      console.error('❌ Authentication failed:', error);
      // Clean up URL parameters
      const newUrl = window.location.pathname;
      window.history.replaceState({}, '', newUrl);
      setIsAuthenticated(false);
    }

    // Check auth status
    if (authService) {
      authService.getAuthStatus().then((status) => {
        setIsAuthenticated(status.isAuthenticated);
      });
    }

    // Listen for postMessage from popup (widget mode)
    const messageHandler = (event: MessageEvent) => {
      // Only process if it's an auth message (type check happens first for security)
      if (event.data && event.data.type === 'orion-auth-success') {
        // Accept messages from widget frontend origin, main origin, or same origin
        // When in iframe, the popup's postMessage comes from the widget domain
        const widgetOrigin = 'https://orion-widget.web.app';
        const mainOrigin = 'https://orion-ai-hk.web.app';
        const isAllowedOrigin = event.origin === widgetOrigin || 
                               event.origin === mainOrigin || 
                               event.origin === window.location.origin;
        
        // For iframe scenarios, be more permissive with origin validation
        // The token itself is the security measure, not just the origin
        if (!isAllowedOrigin) {
          // Log but don't block - in iframe scenarios, origin might vary
          console.warn(`⚠️ Message from unexpected origin: ${event.origin}, but processing anyway for iframe compatibility`);
        }
        if (event.data.token) {
          // Set cookie on frontend domain so it's available for API calls
          const isSecure = window.location.protocol === 'https:';
          const cookieOptions = [
            `orion_auth_token=${event.data.token}`,
            `path=/`,
            `max-age=${60 * 60 * 24 * 7}`, // 7 days
            `SameSite=None`, // Required for cross-origin
            isSecure ? 'Secure' : '', // Required for SameSite=None
          ].filter(Boolean).join('; ');
          document.cookie = cookieOptions;
          
          // Store in localStorage - this is critical for the Authorization header
          localStorage.setItem('orion_auth_token', event.data.token);
          
          // Verify it was stored
          const stored = localStorage.getItem('orion_auth_token');
          if (stored !== event.data.token) {
            console.error('⚠️ Failed to store token in localStorage');
          }
        }
        setIsAuthenticated(true);
        loadMessages(); // Reload messages after auth
      } else if (event.data.type === 'orion-auth-error') {
        console.error('❌ Authentication failed:', event.data.error);
        setIsAuthenticated(false);
      }
    };

    window.addEventListener('message', messageHandler);

    loadMessages();

    return () => {
      window.removeEventListener('message', messageHandler);
    };
  }, [authService, loadMessages]);

  const scrollToBottom = () => {
    const container = messagesContainerRef.current;
    if (container) container.scrollTop = 0;
  };

  const handleScroll = (e: React.UIEvent<HTMLDivElement>) => {
    const { scrollTop } = e.currentTarget;
    if (scrollTop <= 10 && hasMoreMessages && !isLoadingMore) {
      loadMoreMessages();
    }
  };

  useEffect(() => {
    if (!isLoadingMore) scrollToBottom();
  }, [messages, isLoadingMore]);

  const loadMoreMessages = React.useCallback(async () => {
    if (!hasMoreMessages || isLoadingMore) return;
    await loadMessages(currentPage + 1, true);
  }, [hasMoreMessages, isLoadingMore, currentPage, loadMessages]);

  const handleSendMessage = async (messageText: string) => {
    if (!messageText.trim() || isLoading) return;
    setIsLoading(true);
    try {
      const userMessage: ChatMessage = {
        _id: `temp_${Date.now()}`,
        role: 'user',
        content: messageText,
        timestamp: new Date().toISOString(),
        tags: [],
      };
      setMessages((prev) => [userMessage, ...prev]);

      const response = await api.sendMessage(messageText);
      if (response.message) {
        setMessages((prev) => [response.message, ...prev]);
      }
    } catch (err) {
      console.error('Error sending message:', err);
      setMessages((prev) => prev.slice(1));
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="h-full w-full bg-slate-50 flex flex-col">
      {showHeader && (
        <div className="p-4 border-b border-black/10 flex-shrink-0">
          <div className="flex items-center gap-2">
            {brandIcon ?? <DefaultBrandIcon />}
            <h1 className="text-xl font-semibold text-gray-800">{title}</h1>
          </div>
        </div>
      )}

      <div
        ref={messagesContainerRef}
        className="flex-1 overflow-y-auto flex flex-col-reverse"
        onScroll={handleScroll}
      >
        {messages.length === 0 && !isLoading ? (
          <div className="flex justify-center items-center h-full">
            <p className="text-gray-500">Start a conversation with Orion!</p>
          </div>
        ) : (
          <>
            <div />
            {isLoading && (
              <div className="flex justify-center items-end w-full bg-white p-4">
                <div className="flex items-center gap-2 text-gray-600">
                  <div className="flex space-x-1">
                    <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" />
                    <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '0.1s' }} />
                    <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '0.2s' }} />
                  </div>
                  <span className="text-sm">Thinking...</span>
                </div>
              </div>
            )}
            {messages.map((message) => (
              <ChatMessage 
                key={message._id} 
                message={message}
                usePopup={usePopup}
                authService={authService}
                onAuthSuccess={() => loadMessages()}
              />
            ))}
            {isLoadingMore && (
              <div className="flex justify-center py-4">
                <div className="flex items-center gap-2 text-gray-500">
                  <div className="w-4 h-4 border-2 border-gray-300 border-t-blue-500 rounded-full animate-spin" />
                  <span className="text-sm">Loading more messages...</span>
                </div>
              </div>
            )}
          </>
        )}
      </div>

      <div className="flex-shrink-0 px-4">
        <MessageInput onSendMessage={handleSendMessage} isLoading={isLoading} />
      </div>
    </div>
  );
};

const ChatMessage: React.FC<{ 
  message: ChatMessage;
  usePopup?: boolean;
  authService?: any;
  onAuthSuccess?: () => void;
}> = ({ message, usePopup, authService, onAuthSuccess }) => {
  const isUser = message.role === 'user';

  return (
    <div className="flex justify-center items-end w-full bg-white">
      <div className="p-4 w-full max-w-4xl">
        <div className={`flex ${isUser ? 'justify-end' : 'justify-start'}`}>
          <div className={`max-w-[85%] ${isUser ? 'ml-auto' : 'mr-auto'}`}>
            {isUser ? (
              <div className="bg-blue-500 text-white rounded-2xl rounded-br-md px-4 py-3 shadow-sm">
                <span className="whitespace-pre-line text-sm leading-relaxed">{message.content}</span>
              </div>
            ) : (
              <div className="text-gray-800 font-normal text-sm break-words">
                <div className="prose prose-sm max-w-none">
                  <ReactMarkdown
                    remarkPlugins={[remarkGfm]}
                    components={{
                      p: ({ children }) => <p className="mb-2 last:mb-0">{children}</p>,
                      ul: ({ children }) => <ul className="list-disc list-inside mb-2">{children}</ul>,
                      ol: ({ children }) => <ol className="list-decimal list-inside mb-2">{children}</ol>,
                      li: ({ children }) => <li className="mb-1">{children}</li>,
                      a: ({ href, children }: { href?: string; children: React.ReactNode }) => {
                          // Intercept ALL auth links - always use authService if available
                          const isAuthLink = href?.includes('/api/auth/google');
                          
                          if (isAuthLink) {
                            // Always intercept auth links, even if authService is not ready
                            // This prevents navigation to the API URL
                            return (
                              <a
                                href="#"
                                onClick={(e) => {
                                  e.preventDefault();
                                  e.stopPropagation();
                                  
                                  if (authService) {
                                    // Use authService for authentication
                                    authService.signInWithGoogle(
                                      () => {
                                        // Reload messages after successful auth
                                        onAuthSuccess?.();
                                      },
                                      (error: string) => {
                                        console.error('Auth error:', error);
                                      }
                                    );
                                  } else {
                                    // Fallback: if authService is not ready, create it on the fly
                                    // URLs are now hardcoded in AuthService
                                    const tempAuthService = new AuthService({ usePopup: usePopup || false });
                                    tempAuthService.signInWithGoogle(
                                      () => {
                                        onAuthSuccess?.();
                                      },
                                      (error: string) => {
                                        console.error('Auth error:', error);
                                      }
                                    );
                                  }
                                }}
                                onMouseDown={(e) => {
                                  // Prevent default link behavior on mousedown too
                                  if (e.button === 0) { // Left click only
                                    e.preventDefault();
                                  }
                                }}
                                onAuxClick={(e) => {
                                  // Prevent middle-click or right-click from opening in new tab
                                  if (e.button !== 0) {
                                    e.preventDefault();
                                  }
                                }}
                                className="text-blue-600 hover:text-blue-800 underline font-medium cursor-pointer"
                              >
                                {children}
                              </a>
                            );
                          }
                          
                          // For non-auth links, allow normal navigation
                          return (
                            <a
                              href={href}
                              target="_blank"
                              rel="noopener noreferrer"
                              className="text-blue-600 hover:text-blue-800 underline font-medium"
                            >
                              {children}
                            </a>
                          );
                        },
                      code: ({ children, className }) =>
                        !className ? (
                          <code className="bg-gray-100 px-1 py-0.5 rounded text-sm font-mono">{children}</code>
                        ) : (
                          <code className="block bg-gray-100 p-2 rounded text-sm font-mono overflow-x-auto">{children}</code>
                        ),
                      pre: ({ children }) => (
                        <pre className="bg-gray-100 p-2 rounded text-sm font-mono overflow-x-auto mb-2">{children}</pre>
                      ),
                      blockquote: ({ children }) => (
                        <blockquote className="border-l-4 border-gray-300 pl-4 italic mb-2">{children}</blockquote>
                      ),
                    }}
                  >
                    {message.content}
                  </ReactMarkdown>
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default ChatScreen;
