import { useState, useMemo } from 'react';
import { X, MessageCircle } from 'lucide-react';
import { WIDGET_FRONTEND_URL } from '../config/constants';

export type OrionChatBubbleProps = {
  /**
   * Base URL of the Orion frontend (where /widget page is hosted)
   * Defaults to hardcoded production URL
   */
  widgetUrl?: string;
  /**
   * Position of the chat bubble
   */
  position?: 'bottom-right' | 'bottom-left';
  /**
   * Z-index for the widget
   */
  zIndex?: number;
  /**
   * Custom label for the chat button
   */
  buttonLabel?: string;
  /**
   * Callback when widget opens/closes
   */
  onToggle?: (isOpen: boolean) => void;
};

/**
 * Simple standalone chat bubble widget
 * 
 * This is a minimal, self-contained chat widget that works independently.
 * No communication with the host page needed - just a simple chat bubble.
 * 
 * Usage:
 * ```tsx
 * <OrionChatBubble 
 *   widgetUrl="https://orion-ai-hk.web.app"
 *   apiBaseUrl="https://asia-southeast1-orion-ai-hk.cloudfunctions.net/api"
 * />
 * ```
 */
export default function OrionChatBubble({
  widgetUrl = WIDGET_FRONTEND_URL,
  position = 'bottom-right',
  zIndex = 2147483000,
  buttonLabel,
  onToggle,
}: OrionChatBubbleProps) {
  const [isOpen, setIsOpen] = useState(false);

  const sideClass = position === 'bottom-left' ? 'left-4' : 'right-4';

  const toggleChat = () => {
    const newState = !isOpen;
    setIsOpen(newState);
    onToggle?.(newState);
  };

        // Build iframe URL (no query params needed - URLs are hardcoded)
        const iframeUrl = useMemo(() => {
          return new URL('/widget', widgetUrl).toString();
        }, [widgetUrl]);

  return (
    <div className="orion-chat-bubble" style={{ zIndex }}>
      {/* Chat Button (FAB) */}
      <button
        type="button"
        aria-label={isOpen ? 'Close chat' : 'Open chat'}
        onClick={toggleChat}
        className={`fixed ${sideClass} bottom-4 inline-flex items-center justify-center gap-2 rounded-full shadow-lg bg-blue-600 text-white hover:bg-blue-700 active:bg-blue-800 transition-all duration-200 px-4 py-3 ${
          isOpen ? 'rotate-180' : ''
        }`}
        style={{ zIndex }}
      >
        {isOpen ? (
          <X size={20} />
        ) : (
          <>
            <MessageCircle size={20} />
            {buttonLabel && <span className="text-sm font-semibold">{buttonLabel}</span>}
          </>
        )}
      </button>

      {/* Chat Window */}
      {isOpen && (
        <>
          {/* Backdrop */}
          <div
            className="fixed inset-0 bg-black/40 animate-fade-in"
            onClick={toggleChat}
            style={{ zIndex: zIndex - 1 }}
          />

          {/* Chat Container */}
          <div
            className={`fixed ${sideClass} bottom-20 w-[min(420px,calc(100vw-2rem))] h-[min(640px,calc(100vh-6rem))] bg-white rounded-2xl shadow-2xl overflow-hidden border border-gray-200 animate-slide-up`}
            style={{ zIndex: zIndex - 1 }}
          >
            <iframe
              src={iframeUrl}
              title="Orion Chat"
              allow="camera; microphone; geolocation"
              sandbox="allow-same-origin allow-scripts allow-forms allow-popups allow-popups-to-escape-sandbox allow-modals"
              className="w-full h-full border-0"
              style={{ display: 'block' }}
            />
          </div>
        </>
      )}
    </div>
  );
}
