import { useState } from 'react';
import { X, MessageCircle } from 'lucide-react';
import ChatScreen from '../components/ChatScreen';
import { chatApi } from '../services/api';
import type { ChatApi } from '../services/api';

export type OrionChatWidgetProps = {
  title?: string;
  defaultOpen?: boolean;
  zIndex?: number;
  position?: 'bottom-right' | 'bottom-left';
  fabLabel?: string;
  onOpenChange?: (open: boolean) => void;
  api?: ChatApi; // Optional - defaults to chatApi with hardcoded URLs
};

export default function OrionChatWidget({
  title = 'Orion Chat',
  defaultOpen = false,
  zIndex = 2147483000,
  position = 'bottom-right',
  fabLabel,
  onOpenChange,
  api,
}: OrionChatWidgetProps) {
  const [open, setOpen] = useState(defaultOpen);

  const sideClass = position === 'bottom-left' ? 'left-4' : 'right-4';

  const setOpenSafe = (next: boolean) => {
    setOpen(next);
    onOpenChange?.(next);
  };

  return (
    <div className="orion-widget">
      {/* FAB */}
      <button
        type="button"
        aria-label={fabLabel ?? (open ? 'Close chat' : 'Open chat')}
        onClick={() => setOpenSafe(!open)}
        className={`fixed ${sideClass} bottom-4 inline-flex items-center justify-center gap-2 rounded-full shadow-lg bg-blue-600 text-white hover:bg-blue-700 active:bg-blue-800 transition-colors px-4 py-3`}
        style={{ zIndex }}
      >
        <MessageCircle size={18} />
        <span className="text-sm font-semibold">{fabLabel ?? 'Chat'}</span>
      </button>

      {/* Modal */}
      {open && (
        <div className="fixed inset-0" style={{ zIndex: zIndex - 1 }}>
          <div
            className="absolute inset-0 bg-black/40 animate-fade-in"
            onClick={() => setOpenSafe(false)}
          />

          <div
            className={`absolute ${sideClass} bottom-20 w-[min(420px,calc(100vw-2rem))] h-[min(640px,calc(100vh-6rem))] bg-white rounded-2xl shadow-2xl overflow-hidden border border-black/10 animate-slide-up flex flex-col`}
          >
            <div className="flex items-center justify-between px-4 py-3 border-b border-black/10 bg-white flex-shrink-0">
              <div className="flex items-center gap-2">
                <div className="w-6 h-6 rounded-full bg-blue-600 text-white flex items-center justify-center text-xs font-bold">
                  O
                </div>
                <div className="font-semibold text-gray-800">{title}</div>
              </div>
              <button
                type="button"
                aria-label="Close chat"
                onClick={() => setOpenSafe(false)}
                className="p-2 rounded-lg hover:bg-gray-100 active:bg-gray-200"
              >
                <X size={18} className="text-gray-700" />
              </button>
            </div>

            <div className="flex-1 min-h-0">
              <ChatScreen 
                api={api || chatApi} 
                showHeader={false}
                usePopup={true}
              />
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

