/**
 * Authentication service for Orion Chat
 * Handles both popup (widget) and redirect (full web app) flows
 */

import { openAuthPopup, isInPopup } from '../utils/authPopup';
import { API_BASE_URL, FRONTEND_URL, WIDGET_FRONTEND_URL } from '../config/constants';

export interface AuthServiceOptions {
  usePopup?: boolean; // Force popup mode (for widget)
}

export class AuthService {
  private apiBaseUrl: string;
  private frontendUrl: string;
  private usePopup: boolean;

  constructor(options: AuthServiceOptions = {}) {
    // Use centralized config - no need to pass URLs
    this.apiBaseUrl = API_BASE_URL;
    this.frontendUrl = FRONTEND_URL;
    
    // Auto-detect if we're in a widget (cross-origin) or full web app
    // Widget: API URL differs from current origin
    // Full web app: API URL matches current origin or is relative
    if (options.usePopup !== undefined) {
      this.usePopup = options.usePopup;
    } else {
      // Try to detect widget mode by checking if API URL hostname differs from current hostname
      try {
        const apiHostname = new URL(this.apiBaseUrl).hostname;
        const currentHostname = window.location.hostname;
        this.usePopup = apiHostname !== currentHostname && apiHostname !== 'localhost' && currentHostname !== 'localhost';
      } catch {
        // If URL parsing fails, assume web app mode
        this.usePopup = false;
      }
    }
  }

  /**
   * Initiate Google OAuth authentication
   */
  async signInWithGoogle(
    onSuccess?: (data: { token?: string; email?: string; name?: string }) => void,
    onError?: (error: string) => void
  ): Promise<void> {
    try {
      // Determine which frontend URL to use (widget or main app)
      const frontendUrl = this.usePopup ? WIDGET_FRONTEND_URL : FRONTEND_URL;
      
      // Get auth URL from backend, passing frontend URL so it knows where to redirect
      const response = await fetch(
        `${this.apiBaseUrl}/api/auth/google?popup=${this.usePopup}&frontend_url=${encodeURIComponent(frontendUrl)}`,
        {
          method: 'GET',
          credentials: 'include', // Include cookies
        }
      );

      if (!response.ok) {
        throw new Error('Failed to get auth URL');
      }

      const data = await response.json();
      const authUrl = data.authUrl;

      if (this.usePopup) {
        // Open popup for widget (cross-origin)
        openAuthPopup({
          authUrl,
          expectedOrigin: this.frontendUrl,
          onSuccess: (authData) => {
            // Set cookie on frontend domain so it's available for API calls
            if (authData.token) {
              const isSecure = window.location.protocol === 'https:';
              const cookieOptions = [
                `orion_auth_token=${authData.token}`,
                `path=/`,
                `max-age=${60 * 60 * 24 * 7}`, // 7 days
                `SameSite=None`, // Required for cross-origin
                isSecure ? 'Secure' : '', // Required for SameSite=None
              ].filter(Boolean).join('; ');
              document.cookie = cookieOptions;
              
              localStorage.setItem('orion_auth_token', authData.token);
            }
            onSuccess?.(authData);
          },
          onError: (error) => {
            console.error('Auth error:', error);
            onError?.(error);
          },
        });
      } else {
        // Redirect for full web app (same-origin)
        window.location.href = authUrl;
      }
    } catch (error) {
      console.error('Error initiating auth:', error);
      onError?.(error instanceof Error ? error.message : 'Authentication failed');
    }
  }

  /**
   * Get authentication status
   */
  async getAuthStatus(): Promise<{
    isAuthenticated: boolean;
    email?: string;
    name?: string;
    userId?: string;
  }> {
    try {
      // Get token from localStorage or cookie
      let token = localStorage.getItem('orion_auth_token');
      if (!token) {
        // Try to read from cookie
        const cookies = document.cookie.split(';');
        for (const cookie of cookies) {
          const [name, value] = cookie.trim().split('=');
          if (name === 'orion_auth_token' && value) {
            token = value;
            localStorage.setItem('orion_auth_token', value);
            break;
          }
        }
      }

      const headers: HeadersInit = {
        'Content-Type': 'application/json',
      };
      
      // Add Authorization header if token exists
      if (token) {
        headers.Authorization = `Bearer ${token}`;
      }

      const response = await fetch(`${this.apiBaseUrl}/api/auth/status`, {
        method: 'GET',
        credentials: 'include',
        headers,
      });

      if (!response.ok) {
        return { isAuthenticated: false };
      }

      const data = await response.json();
      return data;
    } catch (error) {
      console.error('Error getting auth status:', error);
      return { isAuthenticated: false };
    }
  }

  /**
   * Logout user
   */
  async logout(): Promise<void> {
    try {
      await fetch(`${this.apiBaseUrl}/api/auth/logout`, {
        method: 'POST',
        credentials: 'include',
      });
      
      // Clear localStorage
      localStorage.removeItem('orion_auth_token');
      
      // Reload page to clear state
      window.location.reload();
    } catch (error) {
      console.error('Error logging out:', error);
    }
  }
}

/**
 * Handle OAuth callback (used in OAuth callback page)
 * Detects if in popup and sends postMessage to parent, otherwise handles redirect normally
 * Returns true if in popup mode (so UI can show message before closing)
 */
export function handleOAuthCallback(): boolean {
    // Check if we're in a popup
    if (isInPopup()) {
      // Extract auth data from URL
      const urlParams = new URLSearchParams(window.location.search);
      const authStatus = urlParams.get('auth');
      const token = urlParams.get('token');

      if (authStatus === 'success' && token) {
        // Send success message to parent window (widget)
        // When in iframe, window.opener is the iframe window
        // Use '*' origin to allow cross-origin iframe scenarios
        if (window.opener && !window.opener.closed) {
          // Try to send to opener (iframe window)
          window.opener.postMessage(
            {
              type: 'orion-auth-success',
              token,
            },
            '*' // Allow any origin for iframe flexibility
          );
          
          // Also try to send to parent if we're in an iframe
          if (window.parent && window.parent !== window) {
            window.parent.postMessage(
              {
                type: 'orion-auth-success',
                token,
              },
              '*' // Allow any origin for iframe flexibility
            );
          }
        }
        return true; // Indicates popup mode, UI should handle closing
    } else {
      // Send error message to parent window
      const error = urlParams.get('error') || 'Authentication failed';
      if (window.opener && !window.opener.closed) {
        window.opener.postMessage(
          {
            type: 'orion-auth-error',
            error,
          },
          '*'
        );
      }
      return true; // Indicates popup mode, UI should handle closing
    }
  } else {
    // Normal redirect flow for full web app
    // The ChatScreen component will handle the URL parameters
    // No action needed here, just let the page load normally
    return false;
  }
}
