/**
 * Utility for handling OAuth authentication in a popup window
 * Used when widget is embedded on third-party websites (cross-origin)
 */

export interface AuthPopupOptions {
  authUrl: string;
  expectedOrigin: string; // Expected origin for postMessage validation (e.g., 'https://orion-frontend.com')
  onSuccess?: (data: { token?: string; email?: string; name?: string }) => void;
  onError?: (error: string) => void;
  onClose?: () => void;
}

/**
 * Open OAuth popup and handle authentication flow
 * Returns cleanup function to remove event listeners
 */
export function openAuthPopup(options: AuthPopupOptions): () => void {
  const { authUrl, expectedOrigin, onSuccess, onError, onClose } = options;

  // Calculate popup dimensions (centered on screen)
  const width = 500;
  const height = 600;
  const left = window.screenX + (window.outerWidth - width) / 2;
  const top = window.screenY + (window.outerHeight - height) / 2;

  // Open popup window
  const popup = window.open(
    authUrl,
    'orion-auth',
    `width=${width},height=${height},left=${left},top=${top},toolbar=no,menubar=no,scrollbars=yes,resizable=yes`
  );

  if (!popup) {
    onError?.('Popup blocked. Please allow popups for this site.');
    return () => {};
  }

  // Listen for messages from popup
  const messageHandler = (event: MessageEvent) => {
    // Security: Verify message origin matches expected origin
    // But allow messages from the widget frontend domain for iframe scenarios
    const widgetOrigin = 'https://orion-widget.web.app';
    const isExpectedOrigin = event.origin === expectedOrigin || event.origin === widgetOrigin;
    
    if (!isExpectedOrigin) {
      console.warn(`Ignored message from unauthorized origin: ${event.origin}. Expected: ${expectedOrigin} or ${widgetOrigin}`);
      return;
    }

    if (event.data.type === 'orion-auth-success') {
      onSuccess?.(event.data);
      cleanup();
    } else if (event.data.type === 'orion-auth-error') {
      onError?.(event.data.error || 'Authentication failed');
      cleanup();
    }
  };

  // Check if popup is closed manually (user clicks X)
  const checkClosed = setInterval(() => {
    if (popup.closed) {
      onClose?.();
      cleanup();
    }
  }, 500);

  const cleanup = () => {
    window.removeEventListener('message', messageHandler);
    clearInterval(checkClosed);
    if (popup && !popup.closed) {
      popup.close();
    }
  };

  window.addEventListener('message', messageHandler);

  // Return cleanup function
  return cleanup;
}

/**
 * Send auth success message to parent window (used in OAuth callback page when in popup)
 */
export function sendAuthSuccessToParent(data: {
  token?: string;
  email?: string;
  name?: string;
}): void {
  if (window.opener && !window.opener.closed) {
    window.opener.postMessage(
      {
        type: 'orion-auth-success',
        ...data,
      },
      '*' // In production, you might want to specify exact origin, but '*' works for widget flexibility
    );
    // Close popup after a short delay to ensure message is sent
    setTimeout(() => {
      window.close();
    }, 100);
  }
}

/**
 * Send auth error message to parent window (used in OAuth callback page when in popup)
 */
export function sendAuthErrorToParent(error: string): void {
  if (window.opener && !window.opener.closed) {
    window.opener.postMessage(
      {
        type: 'orion-auth-error',
        error,
      },
      '*' // In production, you might want to specify exact origin
    );
    // Close popup after a short delay
    setTimeout(() => {
      window.close();
    }, 100);
  }
}

/**
 * Check if current window is in a popup (opened by window.open)
 */
export function isInPopup(): boolean {
  return !!window.opener && window.opener !== window;
}
