/**
 * Centralized configuration for Orion Chat
 * These URLs are static and don't need to be passed as props
 */

// Production API URL (Firebase Function)
export const API_BASE_URL = 
  import.meta.env.VITE_API_BASE_URL || 
  (import.meta.env.PROD 
    ? 'https://asia-southeast1-orion-ai-hk.cloudfunctions.net/api'
    : 'http://localhost:3001');

// Production Frontend URL
export const FRONTEND_URL = 
  import.meta.env.VITE_FRONTEND_URL || 
  (import.meta.env.PROD 
    ? 'https://orion-ai-hk.web.app'
    : window.location.origin);

// Widget Frontend URL (for iframe embedding)
export const WIDGET_FRONTEND_URL = 
  import.meta.env.VITE_WIDGET_FRONTEND_URL || 
  (import.meta.env.PROD 
    ? 'https://orion-widget.web.app'
    : window.location.origin);
