import React, { useState } from 'react';
import { Send } from 'lucide-react';

interface MessageInputProps {
  onSendMessage: (message: string) => void;
  isLoading: boolean;
}

const MessageInput: React.FC<MessageInputProps> = ({ onSendMessage, isLoading }) => {
  const [message, setMessage] = useState('');

  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const handleSend = () => {
    if (!message.trim()) return;
    
    onSendMessage(message);
    setMessage('');
  };

  return (
    <div className="w-full flex justify-center items-center bg-slate-50 border-t border-black/10 py-4">
      <div className="w-[95vw] shadow-sm rounded-2xl flex flex-col p-2 overflow-hidden bg-white border border-gray-200 md:w-[635px]">
        <div className="flex items-center gap-2">
          <textarea
            id="chat-input-textarea"
            value={message}
            onChange={(e) => setMessage(e.target.value)}
            onKeyDown={handleKeyDown}
            placeholder="Type your message here..."
            className="border-none cursor-text max-h-[50vh] min-h-[40px] mx-2 pt-3 w-full leading-5 text-sm bg-transparent resize-none outline-none text-gray-800 placeholder:text-gray-400 md:max-h-[350px] md:mx-0"
            rows={1}
            disabled={isLoading}
          />
          <button
            onClick={handleSend}
            disabled={!message.trim() || isLoading}
            className="border-none inline-flex justify-center rounded-2xl cursor-pointer opacity-60 ml-4 bg-transparent transition-opacity hover:opacity-100 disabled:cursor-not-allowed"
          >
            {isLoading ? (
              <div className="w-5 h-5 border-2 border-gray-600 border-t-transparent rounded-full animate-spin"></div>
            ) : (
              <Send size={20} className="text-gray-600" />
            )}
          </button>
        </div>
      </div>
    </div>
  );
};

export default MessageInput;