import React from 'react';
import { createRoot, type Root } from 'react-dom/client';
import OrionChatWidget, { type OrionChatWidgetProps } from './OrionChatWidget';
import cssText from './widget.css?inline';

export type InitOrionChatWidgetOptions = Omit<OrionChatWidgetProps, 'api'> & {
  /**
   * DOM element to mount into. If omitted, we append a host element to <body>.
   */
  target?: HTMLElement;
  /**
   * Use Shadow DOM to prevent Tailwind/widget styles leaking into the host page.
   * Defaults to true.
   */
  shadow?: boolean;
};

export type OrionChatWidgetInstance = {
  destroy: () => void;
  host: HTMLElement;
};

function ensureStyle(shadowRoot: ShadowRoot) {
  const existing = shadowRoot.getElementById('orion-chat-widget-style');
  if (existing) return;
  const style = document.createElement('style');
  style.id = 'orion-chat-widget-style';
  style.textContent = cssText;
  shadowRoot.appendChild(style);
}

export function initOrionChatWidget(options: InitOrionChatWidgetOptions): OrionChatWidgetInstance {
  const {
    target,
    shadow = true,
    title,
    defaultOpen,
    zIndex,
    position,
    fabLabel,
    onOpenChange,
  } = options;

  const host = document.createElement('div');
  host.id = `orion-chat-widget-${Math.random().toString(36).slice(2)}`;

  let root: Root;
  let mountEl: HTMLElement;

  if (shadow) {
    const shadowRoot = host.attachShadow({ mode: 'open' });
    ensureStyle(shadowRoot);
    mountEl = document.createElement('div');
    shadowRoot.appendChild(mountEl);
  } else {
    // Note: without Shadow DOM, Tailwind utilities will affect the host page.
    mountEl = host;
  }

  (target ?? document.body).appendChild(host);

  root = createRoot(mountEl);
  root.render(
    React.createElement(
      React.StrictMode,
      null,
      React.createElement(OrionChatWidget, {
        title,
        defaultOpen,
        zIndex,
        position,
        fabLabel,
        onOpenChange,
      }),
    ),
  );

  return {
    host,
    destroy: () => {
      root.unmount();
      host.remove();
    },
  };
}

export { default as OrionChatWidget } from './OrionChatWidget';
export type { OrionChatWidgetProps } from './OrionChatWidget';
export { default as OrionChatWidgetIframe } from './OrionChatWidgetIframe';
export type { OrionChatWidgetIframeProps } from './OrionChatWidgetIframe';
export { default as OrionChatBubble } from './OrionChatBubble';
export type { OrionChatBubbleProps } from './OrionChatBubble';

declare global {
  interface Window {
    OrionChatWidget?: {
      initOrionChatWidget: typeof initOrionChatWidget;
    };
  }
}

// Convenience global for the IIFE build (plain <script> usage)
if (typeof window !== 'undefined') {
  window.OrionChatWidget = window.OrionChatWidget ?? { initOrionChatWidget };
}

