import axios from 'axios';
import type { SendMessageResponse, GetMessagesResponse } from '../types';

export type ChatApi = {
  sendMessage: (message: string) => Promise<SendMessageResponse>;
  getMessages: (page?: number, limit?: number) => Promise<GetMessagesResponse>;
  healthCheck: () => Promise<{ status: string }>;
};

import { API_BASE_URL } from '../config/constants';

export const getDefaultApiBaseUrl = (): string => {
  return API_BASE_URL;
};

export const createChatApi = (baseURL: string): ChatApi => {
  const api = axios.create({
    baseURL,
    timeout: 60000, // 60s for AI response
    headers: { 'Content-Type': 'application/json' },
    withCredentials: true, // Include cookies (for JWT token)
  });

  // Helper function to get JWT token from cookie or localStorage
  // This is called on EVERY request to ensure we always have the latest token
  const getAuthToken = (): string | null => {
    try {
      // First try localStorage (set during auth via postMessage)
      let token = localStorage.getItem('orion_auth_token');
      if (token) return token;
      
      // Fallback: try to read from cookie (for cross-origin scenarios)
      // Note: HTTP-only cookies can't be read, but non-HTTP-only cookies can
      const cookies = document.cookie.split(';');
      for (const cookie of cookies) {
        const [name, value] = cookie.trim().split('=');
        if (name === 'orion_auth_token' && value) {
          // Store in localStorage for future use
          localStorage.setItem('orion_auth_token', value);
          return value;
        }
      }
    } catch (error) {
      // localStorage might be blocked in some iframe scenarios
      console.warn('Failed to access localStorage:', error);
    }
    
    return null;
  };

  // Add request interceptor to include JWT token and timezone in headers
  // This ensures authentication works even if cookies aren't sent cross-origin
  api.interceptors.request.use(
    (config) => {
      // Always try to get token on every request (localStorage might be updated after initial load)
      const token = getAuthToken();
      if (token) {
        // Add Authorization header if token exists
        config.headers.Authorization = `Bearer ${token}`;
      } else {
        // If no token found, remove Authorization header to avoid stale tokens
        delete config.headers.Authorization;
      }
      
      // Add timezone header from browser
      try {
        const timezone = Intl.DateTimeFormat().resolvedOptions().timeZone;
        config.headers['X-Timezone'] = timezone;
      } catch (error) {
        // Browser doesn't support timezone detection, skip
      }
      
      return config;
    },
    (error) => {
      return Promise.reject(error);
    }
  );

  return {
    sendMessage: async (message: string): Promise<SendMessageResponse> => {
      const response = await api.post('/api/chat/message', { message });
      return response.data;
    },

    getMessages: async (page = 1, limit = 20): Promise<GetMessagesResponse> => {
      const response = await api.get(`/api/chat/messages?page=${page}&limit=${limit}`);
      return response.data;
    },

    healthCheck: async (): Promise<{ status: string }> => {
      const response = await api.get('/api/chat/health');
      return response.data;
    },
  };
};

export const chatApi: ChatApi = createChatApi(getDefaultApiBaseUrl());
